-- Retire the 20-question OCEAN/Big-Five psychology quiz and replace it with
-- the 10-question Marriage Compatibility Quiz. Hand-written (not generated by
-- `prisma migrate dev`, which hung trying to reach a shadow database through
-- the pooled Neon connection) — verified against a live read-only count
-- immediately before this migration was authored:
--   psychology_quizzes: 1 row   (the seeded OCEAN quiz)
--   quiz_questions:     20 rows (the seeded OCEAN questions)
--   user_quiz_responses: 0 rows (no code path in the running app has ever
--                                 written to this table)
-- So the DELETEs below remove only seeder-owned content, never real user
-- data, and the subsequent NOT NULL columns are added to tables that are
-- empty for this quiz by the time they run.

-- 1. Remove the retired OCEAN seed data (children first; the FK is
--    ON DELETE CASCADE, so the second delete would cascade regardless, but
--    being explicit keeps this migration's intent readable on its own).
DELETE FROM "quiz_questions" WHERE "quiz_id" = 'ocean-quiz-v1-seed';
DELETE FROM "psychology_quizzes" WHERE "id" = 'ocean-quiz-v1-seed';

-- 2. Drop the OCEAN-specific index and columns on quiz_questions.
DROP INDEX "quiz_questions_ocean_domain_idx";

ALTER TABLE "quiz_questions" DROP COLUMN "ocean_domain",
                             DROP COLUMN "reverse_scored";

-- 3. Drop the now-unused OCEAN domain enum.
DROP TYPE "ocean_domain";

-- 4. New enum describing how two users' answers to a question compare.
CREATE TYPE "question_scoring_type" AS ENUM ('MUST_ALIGN', 'COMPLEMENTARY_TOLERANT', 'HARD_AXIS');

-- 5. Generalized question shape: content-agnostic single-select options plus
--    the option-pair scoring/flag rules, instead of OCEAN-only columns.
--    quiz_questions has 0 rows at this point (step 1), so these NOT NULL
--    columns need no backfill.
ALTER TABLE "quiz_questions" ADD COLUMN     "dimension" TEXT NOT NULL,
                             ADD COLUMN     "scoring_type" "question_scoring_type" NOT NULL,
                             ADD COLUMN     "options" JSONB NOT NULL,
                             ADD COLUMN     "pair_rules" JSONB NOT NULL DEFAULT '[]';

CREATE INDEX "quiz_questions_dimension_idx" ON "quiz_questions"("dimension");

-- 6. user_quiz_responses: drop the OCEAN-shaped computed-score column. No
--    replacement "result" column is added — this quiz's scoring is entirely
--    pairwise (computed from two users' `answers` at compatibility time), so
--    there is no single-user result to store. Add `updated_at` so a retake
--    of the same active quiz can be tracked as an upsert.
ALTER TABLE "user_quiz_responses" DROP COLUMN "ocean_score",
                                  ADD COLUMN     "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
